//! Front-end menus (main menu, new game, character creator, settings, saves, pause screen),
//! rebuilt from the game's UMG widget blueprints under `Content/UI/Menus`.
//!
//! Layout numbers are the blueprints' own (1920x1080 design canvas, see [`ui_scale`]), text comes
//! from the widgets, and settings rows come from `assets/data/menus.json` (generated by
//! `extractor/gen_menu_data.py`). Art is loaded from `assets/game/` (`extractor/export_assets.sh`).

pub mod autoshot;
pub mod creator;
pub mod data;
pub mod main_menu;
pub mod new_game;
pub mod pause;
pub mod saves;
pub mod settings;
pub mod widgets;

use bevy::prelude::*;
use bevy::window::PrimaryWindow;

pub use data::{CharacterProfile, CurrentGame, MenuData};

/// Top-level flow: the front end, or a running world.
#[derive(States, Debug, Clone, Copy, PartialEq, Eq, Hash, Default)]
pub enum AppState {
    #[default]
    MainMenu,
    InGame,
}

/// Which menu page is open. `None` means gameplay has the screen.
#[derive(States, Debug, Clone, Copy, PartialEq, Eq, Hash, Default)]
pub enum MenuScreen {
    #[default]
    Main,
    Modes,
    QuitToDesktop,
    Settings,
    Saves,
    NewGame,
    Creator,
    None,
    Pause,
    DifficultySettings,
    QuitToMainMenu,
    Suicide,
}

impl MenuScreen {
    /// Where `[Esc] Back` goes from this page.
    pub fn back(self, app: AppState) -> Option<MenuScreen> {
        use MenuScreen::*;
        let root = if app == AppState::InGame { Pause } else { Main };
        match self {
            Main => Option::None,
            Modes | NewGame => Some(Main),
            Creator => Some(NewGame),
            QuitToDesktop | Settings | Saves | DifficultySettings | QuitToMainMenu | Suicide => Some(root),
            Pause => Some(MenuScreen::None),
            MenuScreen::None => Some(Pause),
        }
    }
}

/// Every menu button carries one of these; [`on_goto`] handles plain navigation.
#[derive(Component, Clone, Copy)]
pub struct GotoScreen(pub MenuScreen);

/// Game version shown on the main menu and pause screen.
pub const GAME_VERSION: &str = "v0.7.1g";
pub const GAME_UPDATE: &str = "Preparation";

pub struct MenuPlugin;

impl Plugin for MenuPlugin {
    fn build(&self, app: &mut App) {
        app.init_state::<AppState>()
            .init_state::<MenuScreen>()
            .insert_resource(MenuData::load())
            .init_resource::<CurrentGame>()
            .add_plugins((
                widgets::WidgetsPlugin,
                main_menu::MainMenuPlugin,
                new_game::NewGamePlugin,
                creator::CreatorPlugin,
                settings::SettingsPlugin,
                saves::SavesPlugin,
                pause::PausePlugin,
            ))
            .add_systems(Update, (ui_scale, escape_goes_back))
            .add_observer(on_goto);
        if let Ok(dir) = std::env::var("SD_MENU_SHOTS") {
            app.add_plugins(autoshot::AutoshotPlugin { dir });
        }
    }
}

/// The blueprints are laid out on a 1920x1080 canvas with UMG's default DPI curve (scale by
/// the short side). Matching that keeps every offset and size in this module 1:1 with the asset.
fn ui_scale(windows: Query<&Window, With<PrimaryWindow>>, mut scale: ResMut<UiScale>) {
    let Ok(window) = windows.single() else { return };
    let s = (window.width() / 1920.0).min(window.height() / 1080.0);
    if (scale.0 - s).abs() > f32::EPSILON {
        scale.0 = s;
    }
}

pub fn escape_goes_back(
    keys: Res<ButtonInput<KeyCode>>,
    app: Res<State<AppState>>,
    screen: Res<State<MenuScreen>>,
    mut next: ResMut<NextState<MenuScreen>>,
    focus: Res<creator::TextFocus>,
    overlay: Option<Res<crate::gameplay::GameOverlay>>,
) {
    // An open inventory/loot screen takes Esc for itself.
    let overlay_open = overlay.is_some_and(|o| o.is_open());
    if keys.just_pressed(KeyCode::Escape) && focus.0.is_none() && !overlay_open {
        if let Some(to) = screen.get().back(*app.get()) {
            next.set(to);
        }
    }
}

fn on_goto(
    ev: On<bevy::ui_widgets::Activate>,
    buttons: Query<&GotoScreen>,
    mut next: ResMut<NextState<MenuScreen>>,
) {
    if let Ok(GotoScreen(to)) = buttons.get(ev.entity) {
        next.set(*to);
    }
}
